import{_ as s,o as t,c as i,a3 as o}from"./chunks/framework.DH7DibUz.js";const d=JSON.parse('{"title":"SGC symposium 2024","description":"","frontmatter":{"title":"SGC symposium 2024","date":"2024-09-11T00:00:00.000Z","author":"Ludovic Räss","tags":["News","Event"]},"headers":[],"relativePath":"news/sgc-symposium24.md","filePath":"news/sgc-symposium24.md","lastUpdated":1794345340000}'),a={name:"news/sgc-symposium24.md"};function n(r,e,c,p,l,m){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="sgc-symposium-2024" tabindex="-1">SGC symposium 2024 <a class="header-anchor" href="#sgc-symposium-2024" aria-label="Permalink to &quot;SGC symposium 2024&quot;">​</a></h1><p>We are excited to announce that the Swiss Geocomputing Centre will organise a two-days symposium on <a href="/previews/pr-11/events/sgc-symposium24"><strong>Symposium on Bridging Modelling and Data Sciences</strong></a> to be held at the University of Lausanne (Unil) on November 21-22, 2024.</p><p>You will soon find the relevant information about the event: <a href="/previews/pr-11/events/sgc-symposium24"><strong>Symposium on Bridging Modelling and Data Sciences</strong> (https://unil-sgc.github.io/events/sgc-symposium24)</a></p><h2 id="venue" tabindex="-1">Venue <a class="header-anchor" href="#venue" aria-label="Permalink to &quot;Venue&quot;">​</a></h2><p>This event will provide a platform for students and researchers to showcase their work and connect with actors from the public sector and leading tech companies. It aims to cultivate dialogue and potential collaborations in applied computational sciences within the geosciences.</p><p>The symposium will explore intersections across various computational disciplines, including geo-modelling, geospatial data sciences, GIS, and high-performance computing, with a focus on differentiable modelling, AI/ML, GPU-based processing, and effective research practices in reproducibility and open-source development.</p><p>This symposium aims to unite researchers and institutions through computational/spatial modelling expertise and collaborative opportunities. The symposium will further expand the on-going activities to include external experts. It will feature presentations, devote time for idea exchanges, and short courses led by industry leaders, focusing on geospatial sciences and GPU computing.</p>',7)])])}const h=s(a,[["render",n]]);export{d as __pageData,h as default};
